import json, pathlib, re
ROOT=pathlib.Path(__file__).resolve().parents[1]
old=json.load(open(ROOT/'data/source-v4/corpus.json'))
C=['it','en','ar','ru']
def tr(*v): assert len(v)==4;return dict(zip(C,v))
units={u['id']:u for u in old['units']}
items=list(old['items'])
# All translations are authored examples, not runtime machine translation.
def add(id,title,rows,rules):
    units[id]={'id':id,'title':tr(*title),'rules':{l:tr(*r) for l,r in zip(C,rules)},'focus':{l:f'{l}:{id}' for l in C}}
    for i,row in enumerate(rows):
        t=tr(*row);items.append({'id':f'{id}_{i}','unitId':id,'text':t,'speech':t.copy(),'accepted':{l:[s] for l,s in t.items()}})
add('greetings',('Il primo incontro','Your first hello','اللقاء الأول','Первая встреча'),[
('Ciao!','Hello!','مرحبًا!','Привет!'),('Buongiorno!','Good morning!','صباح الخير!','Доброе утро!'),('Grazie!','Thank you!','شكرًا!','Спасибо!')],[
('Ciao è informale; buongiorno si usa anche in contesti formali. Grazie esprime gratitudine.','Ciao is informal; buongiorno also works in formal settings. Grazie expresses thanks.','Ciao تحية غير رسمية، وbuongiorno مناسبة أيضًا للمواقف الرسمية. Grazie للشكر.','Ciao — неформальное приветствие; buongiorno подходит и для официальной обстановки. Grazie означает благодарность.'),
('Hello è una formula generale. Good morning si usa al mattino. Thank you esprime gratitudine.','Hello is a general greeting. Good morning is used in the morning. Thank you expresses gratitude.','Hello تحية عامة. Good morning تحية الصباح. Thank you للتعبير عن الشكر.','Hello — обычное приветствие. Good morning говорят утром. Thank you выражает благодарность.'),
('Iniziamo con espressioni arabe intere: مرحبًا per salutare e شكرًا per ringraziare. Si legge da destra a sinistra.','Start with whole Arabic expressions: مرحبًا for hello and شكرًا for thanks. Read from right to left.','ابدأ بتعبيرات كاملة: مرحبًا للتحية، وشكرًا للشكر. نقرأ من اليمين إلى اليسار.','Начните с целых выражений: مرحبًا — приветствие, شكرًا — благодарность. Читайте справа налево.'),
('Привет è informale; Доброе утро significa buongiorno al mattino. Osserva le lettere cirilliche, senza confonderle con quelle latine.','Привет is informal; Доброе утро means good morning. Notice the Cyrillic letters rather than treating them as Latin letters.','Привет تحية غير رسمية، وДоброе утро تحية الصباح. انتبه إلى الحروف السيريلية ولا تعاملها كحروف لاتينية.','Привет — неформальное приветствие; Доброе утро говорят утром. Обратите внимание на кириллицу.')])
add('numbers',('Uno, due, tre','One, two, three','واحد، اثنان، ثلاثة','Один, два, три'),[
('un libro','one book','كتاب واحد','одна книга'),('due libri','two books','كتابان','две книги'),('tre libri','three books','ثلاثة كتب','три книги')],[
('Con due e tre, libro diventa libri. Un qui indica la quantità di uno.','With due and tre, libro becomes libri. Un here indicates a quantity of one.','مع due وtre تتحول libro إلى libri. تدل un هنا على العدد واحد.','После due и tre используется libri. Un здесь означает количество один.'),
('Dopo two e three aggiungi -s a book: books. One book resta singolare.','After two and three add -s to book: books. One book stays singular.','بعد two وthree أضف ‎-s إلى book فتصبح books. مع one يبقى الاسم مفردًا.','После two и three добавьте к book окончание -s: books. One book — единственное число.'),
('L’arabo distingue singolare كتاب, duale كتابان e plurale كتب. Per ora impara questi gruppi interi, senza generalizzare a tutti i nomi.','Arabic distinguishes singular كتاب, dual كتابان and plural كتب. Learn these chunks first; not every noun follows this pattern.','ميز بين المفرد كتاب والمثنى كتابان والجمع كتب. تعلم هذه التراكيب أولًا؛ ليست جميع الأسماء على النمط نفسه.','В арабском есть единственное число كتاب, двойственное كتابان и множественное كتب. Пока запомните эти сочетания: не все существительные образуются так же.'),
('Книга è femminile: одна книга, две книги. Dopo три si usa ancora книги. Non è il plurale ordinario dopo qualsiasi numero.','Книга is feminine: одна книга, две книги. After три use книги too. Number constructions have their own patterns.','Книга مؤنثة: одна книга وдве книги. بعد три نستخدم книги أيضًا. للأعداد تراكيب خاصة.','Книга — женского рода: одна книга, две книги, три книги. Форма после числительного зависит от числа.')])
add('possession',('Quello che ho','What I have','ما أملكه','Что у меня есть'),[
('Io ho un libro.','I have a book.','عندي كتاب.','У меня есть книга.'),('Lei ha una casa.','She has a house.','عندها بيت.','У неё есть дом.'),('Lui ha una penna.','He has a pen.','عنده قلم.','У него есть ручка.')],[
('Con io usa ho, con lei e lui usa ha. L’h è scritta ma non pronunciata.','Use ho with io and ha with lei or lui. The written h is silent.','استخدم ho مع io وha مع lei أو lui. حرف h مكتوب ولا ينطق.','С io используйте ho, с lei и lui — ha. Буква h не произносится.'),
('Con I usa have; con she e he usa has. Non dire she have.','Use have with I, and has with she or he. Do not use she have.','استخدم have مع I، وhas مع she وhe. لا تقل she have.','С I используется have, а с she и he — has. Не говорите she have.'),
('Nei modelli عندي significa ho; عندها e عنده significano lei ha e lui ha. Il possessore è indicato dalla terminazione.','In these models عندي means I have; عندها and عنده mean she has and he has. The ending identifies the possessor.','في هذه النماذج: عندي للمتكلم، وعندها للمؤنث، وعنده للمذكر. تحدد النهاية صاحب الشيء.','В этих образцах عندي означает «у меня есть», عندها — «у неё есть», عنده — «у него есть». Владельца указывает окончание.'),
('Impara У меня есть come gruppo: significa ho. Меня, неё e него sono le forme usate dopo у.','Learn У меня есть as a chunk meaning I have. Меня, неё and него are the forms used after у.','تعلم У меня есть كوحدة بمعنى عندي. Меня وнеё وнего هي الصيغ المستخدمة بعد у.','Конструкция У меня есть выражает наличие. После у используются формы меня, неё, него.')])
add('questions',('Le prime domande','First questions','الأسئلة الأولى','Первые вопросы'),[
('Dove abiti?','Where do you live?','أين تسكن؟','Где ты живёшь?'),('Che cosa leggi?','What do you read?','ماذا تقرأ؟','Что ты читаешь?'),('Parli inglese?','Do you speak English?','هل تتكلم الإنجليزية؟','Ты говоришь по-английски?')],[
('Dove chiede un luogo; che cosa chiede un oggetto o un’attività. La forma verbale qui è quella di tu.','Dove asks about a place; che cosa asks about an object or activity. These verb forms address tu.','Dove للسؤال عن مكان، وche cosa عن شيء أو نشاط. صيغ الأفعال هنا مع tu.','Dove спрашивает о месте, che cosa — о предмете или действии. Здесь используются формы для tu.'),
('Nel presente semplice: do + you + verbo base. Dove o cosa precedono do nelle domande del modello.','In simple-present questions use do + you + base verb. Where or what comes before do in these examples.','في أسئلة المضارع البسيط استخدم do + you + الفعل الأساسي. تسبق Where أوWhat كلمة do في النماذج.','В вопросах Present Simple: do + you + начальная форма глагола. Where или what ставится перед do.'),
('أين chiede dove; ماذا chiede che cosa; هل introduce qui una domanda sì/no. I modelli si rivolgono a un uomo.','أين asks where; ماذا asks what; هل introduces a yes/no question here. These models address one man.','أين للمكان، وماذا للسؤال عن الشيء أو الفعل، وهل لسؤال إجابته نعم أو لا. النماذج تخاطب رجلًا واحدًا.','أين спрашивает «где», ماذا — «что», هل вводит вопрос «да/нет». Эти примеры обращены к одному мужчине.'),
('Где significa dove, что significa che cosa. Non inserire un equivalente di do: la domanda sì/no si distingue anche con l’intonazione.','Где means where and что means what. No equivalent of do is needed; intonation also marks yes/no questions.','Где تعني أين، وчто تعني ماذا. لا نضيف ما يقابل do؛ ويساهم التنغيم في تمييز سؤال نعم أو لا.','Где — вопрос о месте, что — о предмете или действии. Вспомогательный глагол do не нужен; важна интонация.')])
add('plural',('Più di uno','More than one','أكثر من واحد','Больше одного'),[
('I libri sono nuovi.','The books are new.','الكتب جديدة.','Книги новые.'),('Le case sono grandi.','The houses are big.','البيوت كبيرة.','Дома большие.'),('Le porte sono nuove.','The doors are new.','الأبواب جديدة.','Двери новые.')],[
('Al plurale cambiano articolo, nome e aggettivo: il libro nuovo → i libri nuovi; la porta nuova → le porte nuove. Usa sono.','In the plural change article, noun and adjective: il libro nuovo → i libri nuovi; la porta nuova → le porte nuove. Use sono.','في الجمع تتغير الأداة والاسم والصفة: il libro nuovo → i libri nuovi؛ وla porta nuova → le porte nuove. استخدم sono.','Во множественном числе меняются артикль, существительное и прилагательное: il libro nuovo → i libri nuovi; la porta nuova → le porte nuove. Используйте sono.'),
('Books, houses e doors sono plurali. Usa are, non is. New e big non aggiungono -s.','Books, houses and doors are plural. Use are, not is. New and big do not take -s.','Books وhouses وdoors جمع. استخدم are لا is. لا تضف ‎-s إلى new أوbig.','Books, houses и doors — множественное число. Используйте are, не is. Прилагательные new и big не получают -s.'),
('Questi plurali non umani prendono una qualità al femminile singolare: الكتب جديدة. I plurali كتب، بيوت، أبواب si imparano con il nome.','These nonhuman plurals take a feminine singular adjective: الكتب جديدة. Learn كتب، بيوت، أبواب with their singular nouns.','تأخذ جموع غير العاقل هنا صفة مفردة مؤنثة: الكتب جديدة. تعلم كتب وبيوت وأبواب مع مفرداتها.','С этими неодушевлёнными множественными существительными прилагательное имеет форму женского единственного числа: الكتب جديدة. Запомните формы كتب، بيوت، أبواب.'),
('L’aggettivo si accorda al plurale: книги новые, дома большие. Дома ha qui l’accento sulla seconda sillaba.','Adjectives agree in the plural: книги новые, дома большие. Here дома is stressed on the second syllable.','تتوافق الصفة مع الجمع: книги новые وдома большие. يقع النبر في дома هنا على المقطع الثاني.','Прилагательные согласуются во множественном числе: книги новые, дома большие. Здесь в слове дома ударение на последнем слоге.')])
add('past',('Raccontare ieri','Talking about yesterday','الحديث عن الأمس','Рассказываем о вчерашнем дне'),[
('Anna ha letto un libro ieri.','Anna read a book yesterday.','قرأت آنا كتابًا أمس.','Анна прочитала книгу вчера.'),('Marco ha bevuto tè ieri.','Marco drank tea yesterday.','شرب ماركو الشاي أمس.','Марко пил чай вчера.'),('Anna ha scritto una lettera ieri.','Anna wrote a letter yesterday.','كتبت آنا رسالة أمس.','Анна написала письмо вчера.')],[
('Qui il passato prossimo usa ha + participio: letto, bevuto, scritto. Sono participi irregolari, non forme in -ato.','Here the passato prossimo uses ha + participle: letto, bevuto, scritto. These participles are irregular.','نستخدم هنا ha + اسم المفعول في الماضي المركب: letto وbevuto وscritto. هذه صيغ غير منتظمة.','Здесь passato prossimo образуется с ha + причастие: letto, bevuto, scritto. Эти причастия неправильные.'),
('Read, drank e wrote sono forme del passato. Il passato di read si scrive uguale al presente, ma si pronuncia diversamente.','Read, drank and wrote are past forms. Past read has the same spelling as present read but a different pronunciation.','Read وdrank وwrote صيغ ماضية. يكتب ماضي read مثل المضارع، لكن نطقه مختلف.','Read, drank и wrote — формы прошедшего времени. Прошедшее read пишется как настоящее, но произносится иначе.'),
('Nel passato قرأت e كتبت hanno la terminazione femminile -ت con آنا. شرب con ماركو è maschile.','In the past, قرأت and كتبت have the feminine ending -ت with آنا. شرب with ماركو is masculine.','في الماضي تنتهي قرأت وكتبت بتاء التأنيث مع آنا. أما شرب مع ماركو فصيغة مذكر.','В прошедшем قرأت и كتبت имеют окончание женского рода -ت с آنا. شرب с ماركو — мужской род.'),
('Nel passato il verbo concorda col genere: прочитала e написала con Анна, пил con Марко. I verbi di lettura e scrittura indicano qui azioni completate.','Past verbs agree with gender: прочитала and написала with Анна, пил with Марко. The reading and writing examples describe completed actions.','يتوافق فعل الماضي مع الجنس: прочитала وнаписала مع Анна، وпил مع Марко. مثالَا القراءة والكتابة يدلان على فعلين مكتملين.','В прошедшем времени глагол согласуется по роду: прочитала и написала с Анна, пил с Марко. Чтение и письмо здесь представлены как завершённые действия.')])
add('future',('Progetti per domani','Plans for tomorrow','خطط الغد','Планы на завтра'),[
('Domani leggerò un libro.','Tomorrow I will read a book.','غدًا سأقرأ كتابًا.','Завтра я прочитаю книгу.'),('Domani scriverò una lettera.','Tomorrow I will write a letter.','غدًا سأكتب رسالة.','Завтра я напишу письмо.'),('Domani andrò a scuola.','Tomorrow I will go to school.','غدًا سأذهب إلى المدرسة.','Завтра я пойду в школу.')],[
('Per io, il futuro di questi verbi finisce in -ò: leggerò, scriverò, andrò. Andrò usa una radice irregolare.','For io, these future forms end in -ò: leggerò, scriverò, andrò. Andrò has an irregular stem.','تنتهي صيغ المستقبل هذه مع io بـ‎-ò: leggerò وscriverò وandrò. جذر andrò غير منتظم.','Для io эти формы будущего заканчиваются на -ò: leggerò, scriverò, andrò. У andrò неправильная основа.'),
('In questi progetti usa will + verbo base. Non aggiungere -s o una forma passata dopo will.','In these plans use will + base verb. Do not add -s or a past form after will.','استخدم في هذه الخطط will + الفعل الأساسي. لا تضف ‎-s أو صيغة ماضية بعد will.','В этих планах используйте will + начальную форму глагола. После will не добавляйте -s и не ставьте прошедшую форму.'),
('سـ prima del presente esprime qui il futuro: سأقرأ، سأكتب، سأذهب. غدًا significa domani.','سـ before the present verb expresses the future here: سأقرأ، سأكتب، سأذهب. غدًا means tomorrow.','تعبر سـ قبل المضارع هنا عن المستقبل: سأقرأ، سأكتب، سأذهب. وغدًا ظرف للمستقبل.','Приставка سـ перед настоящей формой выражает будущее: سأقرأ، سأكتب، سأذهب. غدًا — «завтра».'),
('Прочитаю e напишу sono futuri perfettivi: puntano a un risultato. Пойду indica qui l’inizio di uno spostamento a piedi.','Прочитаю and напишу are perfective future forms, focusing on a result. Пойду here marks setting off on foot.','Прочитаю وнапишу صيغتا مستقبل تام تركزان على النتيجة. وتدل пойду هنا على بدء الذهاب سيرًا.','Прочитаю и напишу — будущее совершенного вида, с акцентом на результат. Пойду здесь означает начало движения пешком.')])
add('ability',('Quello che posso fare','What I can do','ما أستطيع فعله','Что я могу'),[
('Io posso leggere questo libro.','I can read this book.','أستطيع قراءة هذا الكتاب.','Я могу прочитать эту книгу.'),('Lei può aprire la porta.','She can open the door.','تستطيع فتح الباب.','Она может открыть дверь.'),('Noi possiamo aiutare Marco.','We can help Marco.','نستطيع مساعدة ماركو.','Мы можем помочь Марко.')],[
('Potere cambia con il soggetto: posso, può, possiamo. Il verbo seguente resta all’infinito: leggere, aprire, aiutare.','Potere changes with the subject: posso, può, possiamo. The following verb stays in the infinitive: leggere, aprire, aiutare.','يتغير potere مع الفاعل: posso وpuò وpossiamo. يبقى الفعل التالي في المصدر: leggere وaprire وaiutare.','Potere меняется по лицам: posso, può, possiamo. Следующий глагол стоит в инфинитиве: leggere, aprire, aiutare.'),
('Can non cambia con il soggetto. Dopo can usa il verbo senza to: can read, can open, can help.','Can does not change with the subject. Use the verb without to after can: can read, can open, can help.','لا تتغير can مع الفاعل. يأتي بعدها الفعل بلا to: can read وcan open وcan help.','Can не меняется по лицам. После can глагол употребляется без to: can read, can open, can help.'),
('Dopo أستطيع، تستطيع، نستطيع i modelli usano un nome d’azione: قراءة، فتح، مساعدة. Non è l’unico modo per esprimere possibilità.','After أستطيع، تستطيع، نستطيع these models use a verbal noun: قراءة، فتح، مساعدة. This is one way to express ability.','تأتي بعد أستطيع وتستطيع ونستطيع في النماذج مصادر: قراءة وفتح ومساعدة. هذا أحد تراكيب التعبير عن القدرة.','После أستطيع، تستطيع، نستطيع в примерах стоят отглагольные имена: قراءة، فتح، مساعدة. Это один из способов выразить способность.'),
('Могу, может e можем cambiano con il soggetto; dopo usa un infinito. Questi infiniti perfettivi indicano azioni considerate come risultati.','Могу, может and можем change with the subject; follow them with an infinitive. These perfective infinitives focus on results.','تتغير могу وможет وможем مع الفاعل، ويتبعها مصدر. المصادر التامة هنا تركز على نتيجة الفعل.','Могу, может, можем согласуются с подлежащим; дальше стоит инфинитив. Эти инфинитивы совершенного вида выражают действие с результатом.')])
add('preference',('Mi piace','Things I like','ما يعجبني','Что мне нравится'),[
('Mi piace questo libro.','I like this book.','يعجبني هذا الكتاب.','Мне нравится эта книга.'),('Mi piacciono questi libri.','I like these books.','تعجبني هذه الكتب.','Мне нравятся эти книги.'),('Mi piace leggere.','I like reading.','تعجبني القراءة.','Мне нравится читать.')],[
('Il soggetto di piacere è ciò che piace: questo libro piace, questi libri piacciono. Mi significa a me.','The subject of piacere is the thing liked: questo libro piace, questi libri piacciono. Mi means to me.','فاعل piacere هو الشيء المحبوب: questo libro piace وquesti libri piacciono. تعني mi لي.','Подлежащее при piacere — то, что нравится: questo libro piace, questi libri piacciono. Mi означает «мне».'),
('Con I usa like sia con book sia con books. Dopo like, reading è una forma possibile per indicare un’attività.','With I use like for both book and books. Reading after like is one way to name an activity.','مع I استخدم like مع book ومع books. يمكن استخدام reading بعد like للتعبير عن نشاط.','С I используется like и для book, и для books. Форма reading после like — один из способов назвать занятие.'),
('Il verbo concorda con ciò che piace: يعجبني هذا الكتاب; i plurali non umani come الكتب danno تعجبني هذه الكتب. ـني indica me.','The verb agrees with what is liked: يعجبني هذا الكتاب. Nonhuman plurals such as الكتب take تعجبني هذه الكتب. ـني refers to me.','يتوافق الفعل مع الشيء المعجب به: يعجبني هذا الكتاب. وجمع غير العاقل في تعجبني هذه الكتب يعامل كمؤنث مفرد. ـني للمتكلم.','Глагол согласуется с тем, что нравится: يعجبني هذا الكتاب. С неодушевлённым множественным الكتب — تعجبني هذه الكتب. ـني обозначает «мне».'),
('Мне è la forma dativa di я. Usa нравится con книга o un infinito, нравятся con книги.','Мне is the dative form of я. Use нравится with книга or an infinitive, нравятся with книги.','Мне صيغة المجرور غير المباشر لضمير я. استخدم нравится مع книга أو المصدر، وнравятся مع книги.','Мне — дательный падеж местоимения я. Нравится употребляется с книга или инфинитивом, нравятся — с книги.')])
add('comparison',('Fare confronti','Making comparisons','المقارنة','Сравнения'),[
('Questa casa è più grande.','This house is bigger.','هذا البيت أكبر.','Этот дом больше.'),('Questo libro è più interessante.','This book is more interesting.','هذا الكتاب أكثر إثارة للاهتمام.','Эта книга интереснее.'),('Questo tè è migliore.','This tea is better.','هذا الشاي أفضل.','Этот чай лучше.')],[
('Usa più + aggettivo per grande e interessante. Migliore è un comparativo irregolare; non dire più migliore.','Use più + adjective for grande and interessante. Migliore is irregular; do not say più migliore.','استخدم più + الصفة مع grande وinteressante. Migliore صيغة غير منتظمة؛ لا تقل più migliore.','С grande и interessante используйте più + прилагательное. Migliore — неправильная форма; не говорите più migliore.'),
('Big diventa bigger, interesting usa more interesting, good diventa better. Non unire more e better.','Big becomes bigger, interesting uses more interesting, and good becomes better. Do not combine more and better.','تصبح big كلمة bigger، وinteresting مع more، وgood تصبح better. لا تجمع more وbetter.','Big превращается в bigger, interesting — в more interesting, good — в better. Не соединяйте more и better.'),
('أكبر e أفضل sono forme comparative. L’espressione أكثر إثارة للاهتمام è un altro schema: imparala come gruppo.','أكبر and أفضل are comparative forms. أكثر إثارة للاهتمام uses another pattern; learn it as a chunk.','أكبر وأفضل من صيغ التفضيل. أما أكثر إثارة للاهتمام فتركيب آخر؛ تعلمه كوحدة.','أكبر и أفضل — сравнительные формы. أكثر إثارة للاهتمام использует другую конструкцию; запомните её целиком.'),
('Queste forme comparative non cambiano con il genere: больше, интереснее, лучше. Лучше è irregolare.','These comparative forms do not change with gender: больше, интереснее, лучше. Лучше is irregular.','لا تتغير هذه صيغ المقارنة بحسب الجنس: больше وинтереснее وлучше. Лучше غير منتظمة.','Эти сравнительные формы не меняются по роду: больше, интереснее, лучше. Лучше — неправильная форма.')])
add('reasons',('Dire perché','Giving reasons','ذكر السبب','Объясняем причину'),[
('Leggo perché mi piace.','I read because I like it.','أقرأ لأنني أحب القراءة.','Я читаю, потому что мне это нравится.'),('Bevo acqua perché ho sete.','I drink water because I am thirsty.','أشرب الماء لأنني عطشان.','Я пью воду, потому что хочу пить.'),('Studio perché voglio imparare.','I study because I want to learn.','أدرس لأنني أريد أن أتعلم.','Я учусь, потому что хочу научиться.')],[
('Perché introduce il motivo. Non tradurre ho sete parola per parola: è un’espressione con avere.','Perché introduces a reason. Ho sete is an expression with avere; do not translate it word for word.','Perché تقدم السبب. Ho sete تعبير بفعل avere، ولا يترجم حرفيًا.','Perché вводит причину. Ho sete — выражение с avere, его не нужно переводить дословно.'),
('Because collega un’azione al motivo. In inglese usa I am thirsty, non I have thirst.','Because links an action to its reason. Use I am thirsty, not I have thirst.','Because تربط الفعل بسببه. قل I am thirsty لا I have thirst.','Because связывает действие с причиной. Используйте I am thirsty, а не I have thirst.'),
('لأنني significa perché io. Nell’esempio عطشان parla un uomo; una donna può dire عطشانة.','لأنني means because I. عطشان here is said by a man; a woman can say عطشانة.','لأنني تربط السبب بالمتكلم. في مثال عطشان يتكلم رجل، وتقول المرأة عطشانة.','لأنني означает «потому что я». عطشان здесь говорит мужчина; женщина может сказать عطشانة.'),
('Потому что introduce una causa. In questi esempi è preceduto da una virgola. Хочу пить esprime avere sete.','Потому что introduces a reason and is preceded by a comma here. Хочу пить expresses being thirsty.','Потому что تقدم السبب وتسبقها فاصلة هنا. تعبر Хочу пить عن العطش.','Потому что вводит причину; перед ним здесь стоит запятая. Хочу пить означает жажду.')])
add('pronouns',('Al posto del nome','Instead of the noun','بدلًا من الاسم','Вместо существительного'),[
('Io lo leggo.','I read it.','أنا أقرؤه.','Я читаю его.'),('Lei la apre.','She opens it.','هي تفتحها.','Она открывает её.'),('Noi li compriamo.','We buy them.','نحن نشتريها.','Мы покупаем их.')],[
('Lo, la e li precedono qui il verbo. Si riferiscono rispettivamente al libro, alla porta e ai libri.','Lo, la and li come before the verb here. They refer to the book, the door and the books respectively.','تسبق lo وla وli الفعل هنا. وتشير بالترتيب إلى الكتاب والباب والكتب في الإيطالية.','Lo, la, li стоят перед глаголом. Они обозначают соответственно книгу, дверь и книги в итальянских примерах.'),
('It e them seguono il verbo: read it, buy them. It si riferisce a un oggetto singolare; them a più oggetti.','It and them follow the verb: read it, buy them. It refers to one object; them to multiple objects.','تأتي it وthem بعد الفعل: read it وbuy them. It لشيء واحد وthem لأشياء متعددة.','It и them ставятся после глагола: read it, buy them. It обозначает один предмет, them — несколько.'),
('Il pronome oggetto si unisce al verbo: ـه in أقرؤه, ـها in تفتحها. Qui i riferimenti arabi sono كتاب، نافذة، كتب; il plurale non umano usa ـها.','The object pronoun attaches to the verb: ـه in أقرؤه, ـها in تفتحها. The Arabic referents here are كتاب، نافذة، كتب; the nonhuman plural uses ـها.','يتصل ضمير المفعول بالفعل: ـه في أقرؤه وـها في تفتحها. المراجع هنا كتاب ونافذة وكتب؛ ويأخذ جمع غير العاقل ـها.','Объектное местоимение присоединяется к глаголу: ـه в أقرؤه, ـها в تفتحها. Здесь арабские обозначения: كتاب، نافذة، كتب; неодушевлённое множественное использует ـها.'),
('Usa forme oggetto: его, её, их. I riferimenti russi qui sono письмо, дверь, книги. Il genere segue il nome russo, non quello tradotto.','Use object forms: его, её, их. The Russian referents here are письмо, дверь, книги. Gender follows the Russian noun, not its translation.','استخدم صيغ المفعول: его وеё وих. المراجع الروسية هنا письмо وдверь وкниги. يتبع الجنس الاسم الروسي لا ترجمته.','Используйте объектные формы: его, её, их. Здесь имеются в виду письмо, дверь, книги. Род определяется русским существительным.')])
add('relative',('Aggiungere un dettaglio','Adding a detail','إضافة تفصيل','Добавляем подробность'),[
('Questo è il libro che leggo.','This is the book that I read.','هذا هو الكتاب الذي أقرؤه.','Это книга, которую я читаю.'),('Questa è la casa che vedo.','This is the house that I see.','هذا هو البيت الذي أراه.','Это дом, который я вижу.'),('Questa è la porta che apro.','This is the door that I open.','هذا هو الباب الذي أفتحه.','Это дверь, которую я открываю.')],[
('Che collega un nome a una frase che lo descrive. In questi esempi non cambia tra libro, casa e porta.','Che links a noun to a clause describing it. In these examples it does not change with libro, casa or porta.','تربط che الاسم بجملة تصفه. ولا تتغير هنا مع libro وcasa وporta.','Che связывает существительное с описывающим его предложением. В этих примерах форма не меняется с libro, casa и porta.'),
('That introduce qui una relativa sull’oggetto. Nel modello mantenilo; in queste frasi inglesi è possibile anche ometterlo.','That introduces an object relative clause here. Keep it in the tile model; it can also be omitted in these English sentences.','تقدم that هنا جملة موصولية للمفعول. احتفظ بها في نموذج البلاطات؛ ويمكن حذفها في هذه الجمل الإنجليزية.','That вводит определительное придаточное об объекте. Сохраните его в модели с плитками; в этих английских предложениях его также можно опустить.'),
('Qui الذي si riferisce a nomi maschili definiti. Il suffisso ـه nel verbo riprende il nome: الذي أقرؤه.','Here الذي refers to definite masculine nouns. The suffix ـه on the verb refers back to the noun: الذي أقرؤه.','تعود الذي هنا على أسماء مذكرة معرفة. ويعود الضمير ـه في الفعل على الاسم: الذي أقرؤه.','Здесь الذي относится к определённым существительным мужского рода. Суффикс ـه при глаголе отсылает к существительному: الذي أقرؤه.'),
('Которую è femminile accusativo; который qui è maschile inanimato accusativo. Il pronome prende genere dal nome e caso dal ruolo nella relativa.','Которую is feminine accusative; который here is masculine inanimate accusative. The pronoun gets gender from its noun and case from its role in the relative clause.','Которую مؤنث في حالة النصب، وкоторый هنا مذكر غير عاقل في النصب. يتبع الضمير جنس الاسم وحالته حسب دوره في الجملة الموصولية.','Которую — женский род, винительный падеж; который здесь — мужской неодушевлённый, винительный. Род зависит от существительного, падеж — от роли в придаточном.')])
add('conditions',('Se succede…','If it happens…','إذا حدث…','Если это случится…'),[
('Se ho tempo, leggo.','If I have time, I read.','إذا كان عندي وقت، أقرأ.','Если у меня есть время, я читаю.'),('Se ho sete, bevo acqua.','If I am thirsty, I drink water.','إذا كنت عطشان، أشرب الماء.','Если я хочу пить, я пью воду.'),('Se piove, resto a casa.','If it rains, I stay at home.','إذا أمطرت، أبقى في البيت.','Если идёт дождь, я остаюсь дома.')],[
('Qui se + presente descrive una condizione abituale, seguita da una conseguenza al presente. Non è ancora il periodo ipotetico irreale.','Here se + present describes a habitual condition followed by a present consequence. This is not yet an unreal conditional.','تصف se + المضارع هنا شرطًا معتادًا تليه نتيجة بالمضارع. هذا ليس شرطًا غير واقعي بعد.','Здесь se + настоящее выражает привычное условие с результатом в настоящем. Это ещё не нереальное условие.'),
('In queste abitudini: if + presente, poi presente. Con it usa rains; con I usa stay.','For these habits use if + present, then present. With it use rains; with I use stay.','لهذه العادات استخدم if + المضارع ثم المضارع. مع it استخدم rains، ومع I استخدم stay.','Для этих привычных ситуаций: if + настоящее, затем настоящее. С it используется rains, с I — stay.'),
('إذا introduce una condizione. كان o un verbo formalmente passato dopo إذا non impongono qui una traduzione al passato. عطشان si riferisce a un uomo.','إذا introduces a condition. كان or a formally past verb after إذا need not refer to past time here. عطشان refers to a man.','إذا تقدم شرطًا. لا يلزم من كان أو الفعل الماضي بعدها أن يكون المعنى ماضيًا هنا. عطشان وصف لرجل.','إذا вводит условие. كان или формально прошедший глагол после إذا не обязательно означает прошедшее время. عطشان относится к мужчине.'),
('Если introduce la condizione. Дома indica essere a casa; non confonderlo con домой, che indica una direzione.','Если introduces a condition. Дома means at home; do not confuse it with домой, which expresses direction.','Если تقدم الشرط. Дома تعني في البيت؛ لا تخلطها مع домой التي تدل على الاتجاه.','Если вводит условие. Дома обозначает место; домой — направление движения.')])
add('experience',('Già fatto','Already done','قد فعلت ذلك','Уже сделано'),[
('Anna ha già letto questo libro.','Anna has already read this book.','لقد قرأت آنا هذا الكتاب.','Анна уже прочитала эту книгу.'),('Marco ha già scritto la lettera.','Marco has already written the letter.','لقد كتب ماركو الرسالة.','Марко уже написал письмо.'),('Anna ha già aperto la porta.','Anna has already opened the door.','لقد فتحت آنا الباب.','Анна уже открыла дверь.')],[
('Già si inserisce qui tra ha e il participio: ha già letto. Il participio di aprire è aperto.','Già goes between ha and the participle here: ha già letto. The participle of aprire is aperto.','تأتي già هنا بين ha واسم المفعول: ha già letto. اسم المفعول من aprire هو aperto.','Già здесь ставится между ha и причастием: ha già letto. Причастие от aprire — aperto.'),
('Has + participio forma qui il present perfect. Confronta wrote con written e nota already tra has e il participio.','Has + past participle forms the present perfect here. Compare wrote with written and notice already between has and the participle.','يشكل has + اسم المفعول المضارع التام هنا. قارن wrote بـwritten، ولاحظ already بين has واسم المفعول.','Has + причастие образует здесь Present Perfect. Сравните wrote и written; already стоит между has и причастием.'),
('لقد + passato presenta qui un’azione compiuta. La terminazione -ت in قرأت e فتحت indica il soggetto femminile آنا.','لقد + past presents a completed action here. The ending -ت in قرأت and فتحت marks the feminine subject آنا.','تقدم لقد + الماضي هنا فعلًا منجزًا. تدل تاء التأنيث في قرأت وفتحت على الفاعل آنا.','لقد + прошедшее здесь представляет завершённое действие. Окончание -ت в قرأت и فتحت соответствует женскому подлежащему آنا.'),
('Уже significa già. Прочитала, написал e открыла sono perfettivi: il punto è il risultato completato, non la durata.','Уже means already. Прочитала, написал and открыла are perfective: the focus is the completed result, not duration.','Уже تعني قد حدث بالفعل. Прочитала وнаписал وоткрыла تامة؛ التركيز على النتيجة المكتملة لا المدة.','Уже указывает на свершившееся действие. Прочитала, написал, открыла — совершенный вид, с акцентом на результат, не длительность.')])
add('wishes',('Voglio che…','I want you to…','أريد أن…','Я хочу, чтобы…'),[
('Voglio che tu venga.','I want you to come.','أريد أن تأتي.','Я хочу, чтобы ты пришёл.'),('Voglio che lei legga questo libro.','I want her to read this book.','أريد أن تقرأ هذا الكتاب.','Я хочу, чтобы она прочитала эту книгу.'),('Voglio che lui apra la porta.','I want him to open the door.','أريد أن يفتح الباب.','Я хочу, чтобы он открыл дверь.')],[
('Quando cambia il soggetto, voglio che introduce qui il congiuntivo: venga, legga, apra. Non usare vieni dopo che in questo modello.','When the subject changes, voglio che takes the subjunctive here: venga, legga, apra. Do not use vieni after che in this model.','عندما يتغير الفاعل تأتي بعد voglio che هنا صيغة congiuntivo: venga وlegga وapra. لا تستخدم vieni بعد che في هذا النموذج.','При смене подлежащего voglio che здесь требует congiuntivo: venga, legga, apra. В этой модели после che не используется vieni.'),
('Con un altro soggetto, usa want + pronome oggetto + to + verbo: want her to read, want him to open.','With a different subject use want + object pronoun + to + verb: want her to read, want him to open.','مع فاعل مختلف استخدم want + ضمير المفعول + to + الفعل: want her to read وwant him to open.','При другом действующем лице: want + объектное местоимение + to + глагол: want her to read, want him to open.'),
('أن precede qui un verbo al congiuntivo arabo. تأتي si riferisce a tu maschile, تقرأ a lei, يفتح a lui. Le vocali finali non sono valutate in questi modelli non vocalizzati.','أن introduces a subjunctive verb here. تأتي addresses a man, تقرأ refers to her, يفتح to him. Final short vowels are not assessed in these unvocalised models.','تسبق أن هنا فعلًا مضارعًا منصوبًا. تأتي للمخاطب المذكر، وتقرأ للغائبة، ويفتح للغائب. لا تقيم الحركات النهائية في هذه النماذج غير المشكولة.','أن здесь вводит сослагательную форму глагола. تأتي обращено к мужчине, تقرأ относится к ней, يفتح — к нему. Конечные краткие гласные в этих невокализованных моделях не оцениваются.'),
('Dopo хочу, чтобы usa qui una forma morfologicamente passata, anche se il desiderio riguarda il futuro: пришёл, прочитала, открыл. Il primo esempio si rivolge a un uomo.','After хочу, чтобы use a past-shaped verb here even for a future wish: пришёл, прочитала, открыл. The first example addresses a man.','بعد хочу, чтобы نستخدم هنا فعلًا بصيغة الماضي ولو كانت الرغبة للمستقبل: пришёл وпрочитала وоткрыл. المثال الأول يخاطب رجلًا.','После хочу, чтобы здесь стоит форма прошедшего времени даже для будущего желания: пришёл, прочитала, открыл. Первый пример обращён к мужчине.')])
# Explicit contextual variants. They do not license arbitrary changes of meaning.
for it in items:
    if it['id']=='conditions_1':
        it['text']['ar']='إذا كنت عطشانًا، أشرب الماء.';it['speech']['ar']=it['text']['ar'];it['accepted']['ar']=[it['text']['ar']]
    if it['id']=='reasons_1':it['accepted']['ar'].append('أشرب الماء لأنني عطشانة.')
    if it['id']=='wishes_0':it['accepted']['ru'].append('Я хочу, чтобы ты пришла.')
    if it['unitId']=='relative':it['accepted']['en'].append(it['text']['en'].replace(' that ', ' '))
    if it['unitId']=='pronouns':
        it['context']=tr('Il pronome rimanda a un oggetto già nominato; il nome di riferimento può cambiare genere nella traduzione.','The pronoun refers to a previously named object; its grammatical gender can change in translation.','يعود الضمير على شيء سبق ذكره؛ وقد يختلف جنسه النحوي في الترجمة.','Местоимение относится к ранее названному предмету; его род может меняться при переводе.')
    # Add only clear omission of Italian io, not unsupported free-form equivalences.
    if it['text']['it'].startswith('Io '):
        v=it['text']['it'][3:];v=v[0].upper()+v[1:]
        if v not in it['accepted']['it']:it['accepted']['it'].append(v)
    if it['text']['en'].startswith('I will '):it['accepted']['en'].append(it['text']['en'].replace('I will ',"I'll ",1))
    if it['text']['en'].startswith('I do not '):it['accepted']['en'].append(it['text']['en'].replace('I do not ',"I don't ",1))
    it.setdefault('context',tr('Usa il significato e la struttura studiati. Sono accettate le varianti esplicite del corso.','Use the meaning and structure studied. The course accepts its explicit variants.','استخدم المعنى والتركيب المدروسين. يقبل المقرر البدائل المحددة فيه.','Используйте изученные смысл и конструкцию. Принимаются явно предусмотренные варианты.'))
order=['greetings','identity','objects','description','numbers','possession','habits','others','negative','location','requests','questions','plural','past','future','ability','preference','comparison','reasons','pronouns','relative','conditions','experience','wishes']
# Same communicative route, language-specific micro-rules. No CEFR certification claims.
for n,k in enumerate(order):
    units[k]['index']=n;units[k]['chapter']=n//6
    units[k]['prerequisites']={l:([order[n-1]] if n else []) for l in C}
    units[k]['items']=[i['id'] for i in items if i['unitId']==k]
# Introductory chunks also serve as extra matching tiles for the first units.
vrows=[('yes','sì','yes','نعم','да'),('no','no','no','لا','нет'),('please','per favore','please','من فضلك','пожалуйста'),('i','io','I','أنا','я'),('she','lei','she','هي','она'),('he','lui','he','هو','он')]
vocab=[{'id':'v_'+id,'text':tr(*row),'speech':tr(*row),'accepted':{l:[v] for l,v in tr(*row).items()},'unitId':'greetings','vocab':True} for id,*row in vrows]
Cdata={'version':5,'reviewStatus':'authored-not-native-reviewed','units':[units[k] for k in order],'items':items,'vocab':vocab,'languages':C,'directions':[f'{s}>{t}' for s in C for t in C if s!=t],'chapters':[tr('Premiers pas' if False else 'Le fondamenta','The foundations','الأساسيات','Основы'),tr('La vita di ogni giorno','Everyday life','الحياة اليومية','Повседневная жизнь'),tr('Storie e possibilità','Stories & possibilities','حكايات وإمكانات','Истории и возможности'),tr('Sfumature e connessioni','Nuance & connections','دقة وترابط','Оттенки и связи')]}
(ROOT/'data/course.json').write_text(json.dumps(Cdata,ensure_ascii=False,indent=2))
print(len(Cdata['units']),'units',len(items),'aligned items',len(vocab),'vocabulary items',len(Cdata['directions']),'directions')
